using System.Security.Claims;
using Microsoft.EntityFrameworkCore;
namespace TheBarcode.Api;
public static class ModularOperationsEndpoints
{
 public static void MapModularOperationsApi(this WebApplication app){app.MapAccountingApi();app.MapHistoricalSalesApi();var api=app.MapGroup("/api").RequireAuthorization();
 api.MapGet("/modules",()=>Results.Ok(new{mode="OpenPreview",package="All features",modules=new[]{new{key="sales",name="Sales & POS",area="Revenue",status="Active"},new{key="inventory",name="Inventory",area="Stock control",status="Active"},new{key="expenses",name="Expenses",area="Operations",status="Active"},new{key="production",name="Recipes & Production",area="Make to sell",status="Active"},new{key="reports",name="Reports",area="Decision intelligence",status="Active"},new{key="ai",name="Smart Insights",area="Smart guidance",status="Active"}},industries=new[]{"Hospitality","Bakery","Retail","Manufacturing","Services","Other"}}));
 api.MapGet("/recipes",async(AppDbContext db,ClaimsPrincipal p)=>{var demo=Security.IsDemo(p);var recipes=await db.Recipes.AsNoTracking().Where(x=>x.IsDemo==demo).Include(x=>x.Ingredients).OrderByDescending(x=>x.Active).ThenBy(x=>x.Name).ToListAsync();var ids=recipes.Select(x=>x.ProductId).Concat(recipes.SelectMany(x=>x.Ingredients).Select(x=>x.IngredientProductId)).Distinct().ToList();var products=await db.Products.AsNoTracking().Where(x=>ids.Contains(x.Id)).ToDictionaryAsync(x=>x.Id);return Results.Ok(recipes.Select(x=>new{x.Id,x.ProductId,productName=products.GetValueOrDefault(x.ProductId)?.Name??"Missing item",x.Name,x.YieldQuantity,x.Version,x.Active,x.Notes,costPerYield=x.Ingredients.Sum(i=>i.Quantity*(1+i.WastePercent/100)*(products.GetValueOrDefault(i.IngredientProductId)?.CostPrice??0)),ingredients=x.Ingredients.Select(i=>new{i.IngredientProductId,productName=products.GetValueOrDefault(i.IngredientProductId)?.Name??"Missing item",unit=products.GetValueOrDefault(i.IngredientProductId)?.Unit,stock=products.GetValueOrDefault(i.IngredientProductId)?.Stock,i.Quantity,i.WastePercent})}));});
 api.MapPost("/recipes",async(RecipeRequest r,AppDbContext db,ClaimsPrincipal p)=>{var demo=Security.IsDemo(p);if(string.IsNullOrWhiteSpace(r.Name)||r.YieldQuantity<=0||r.Ingredients.Count==0||r.Ingredients.Any(x=>x.Quantity<=0||x.WastePercent<0))return Results.BadRequest(new{error="Name, positive yield and at least one valid ingredient are required"});var ids=r.Ingredients.Select(x=>x.ProductId).Append(r.ProductId).Distinct().ToList();var products=await db.Products.Where(x=>ids.Contains(x.Id)&&x.IsDemo==demo&&x.Active).ToDictionaryAsync(x=>x.Id);if(!products.ContainsKey(r.ProductId)||r.Ingredients.Any(x=>!products.ContainsKey(x.ProductId)))return Results.BadRequest(new{error="Every output and ingredient must be an active item in this account"});if(r.Ingredients.Any(x=>x.ProductId==r.ProductId))return Results.BadRequest(new{error="An output item cannot consume itself"});await using var tx=await db.Database.BeginTransactionAsync();var previous=await db.Recipes.Where(x=>x.ProductId==r.ProductId&&x.IsDemo==demo&&x.Active).ToListAsync();foreach(var old in previous){old.Active=false;old.UpdatedAt=DateTimeOffset.UtcNow;}var recipe=new Recipe{ProductId=r.ProductId,Name=r.Name.Trim(),YieldQuantity=r.YieldQuantity,Version=previous.Select(x=>x.Version).DefaultIfEmpty(0).Max()+1,Notes=r.Notes?.Trim(),IsDemo=demo};foreach(var i in r.Ingredients.GroupBy(x=>x.ProductId).Select(g=>new{Id=g.Key,Quantity=g.Sum(x=>x.Quantity),Waste=g.Max(x=>x.WastePercent)}))recipe.Ingredients.Add(new RecipeIngredient{RecipeId=recipe.Id,IngredientProductId=i.Id,Quantity=i.Quantity,WastePercent=i.Waste});db.Recipes.Add(recipe);db.AuditEvents.Add(Audit(p,"Created","Recipe",recipe.Id,$"{recipe.Name} v{recipe.Version}"));await db.SaveChangesAsync();await tx.CommitAsync();return Results.Created($"/api/recipes/{recipe.Id}",recipe);}).RequireAuthorization(x=>x.RequireRole("Owner","Manager","Storekeeper"));
 api.MapPost("/production-runs",async(ProductionRunRequest r,AppDbContext db,ClaimsPrincipal p)=>{if(r.Quantity<=0)return Results.BadRequest(new{error="Production quantity must be greater than zero"});var demo=Security.IsDemo(p);var recipe=await db.Recipes.Include(x=>x.Ingredients).SingleOrDefaultAsync(x=>x.Id==r.RecipeId&&x.IsDemo==demo&&x.Active);if(recipe is null)return Results.NotFound();var ids=recipe.Ingredients.Select(x=>x.IngredientProductId).Append(recipe.ProductId).Distinct().ToList();var products=await db.Products.Where(x=>ids.Contains(x.Id)&&x.IsDemo==demo&&x.Active).ToDictionaryAsync(x=>x.Id);if(!products.TryGetValue(recipe.ProductId,out var output))return Results.Conflict(new{error="Output item is missing or archived"});var factor=r.Quantity/recipe.YieldQuantity;var needs=recipe.Ingredients.Select(x=>new{x.IngredientProductId,Quantity=x.Quantity*(1+x.WastePercent/100)*factor}).ToList();foreach(var need in needs)if(!products.TryGetValue(need.IngredientProductId,out var ingredient)||ingredient.Stock<need.Quantity)return Results.Conflict(new{error=$"Insufficient {ingredient?.Name??"ingredient"}: need {need.Quantity:0.###}, available {ingredient?.Stock??0:0.###}"});await using var tx=await db.Database.BeginTransactionAsync();decimal cost=0;var staff=StaffId(p);foreach(var need in needs){var ingredient=products[need.IngredientProductId];ingredient.Stock-=need.Quantity;cost+=need.Quantity*ingredient.CostPrice;db.StockMovements.Add(new StockMovement{ProductId=ingredient.Id,StaffId=staff,Type="Production consumption",QuantityChange=-need.Quantity,Notes=$"Recipe {recipe.Name}",OccurredAt=DateTimeOffset.UtcNow});}var oldValue=output.Stock*output.CostPrice;output.Stock+=r.Quantity;output.CostPrice=Math.Round((oldValue+cost)/output.Stock,2);db.StockMovements.Add(new StockMovement{ProductId=output.Id,StaffId=staff,Type="Production output",QuantityChange=r.Quantity,Notes=$"Recipe {recipe.Name}",OccurredAt=DateTimeOffset.UtcNow});var run=new ProductionRun{RecipeId=recipe.Id,ProductId=output.Id,StaffId=staff,QuantityProduced=r.Quantity,TotalCost=cost,Notes=r.Notes?.Trim(),IsDemo=demo};db.ProductionRuns.Add(run);db.AuditEvents.Add(Audit(p,"Completed","ProductionRun",run.Id,$"{r.Quantity:0.###} {output.Unit} {output.Name}; cost {cost:0.00}",r.DeviceId));await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(new{run.Id,run.QuantityProduced,run.TotalCost,unitCost=cost/r.Quantity,outputStock=output.Stock});}).RequireAuthorization(x=>x.RequireRole("Owner","Manager","Storekeeper"));
 api.MapGet("/production-runs",async(AppDbContext db,ClaimsPrincipal p)=>{var demo=Security.IsDemo(p);var rows=await db.ProductionRuns.AsNoTracking().Where(x=>x.IsDemo==demo).OrderByDescending(x=>x.OccurredAt).Take(250).ToListAsync();var ids=rows.Select(x=>x.ProductId).Distinct().ToList();var names=await db.Products.AsNoTracking().Where(x=>ids.Contains(x.Id)).ToDictionaryAsync(x=>x.Id,x=>x.Name);return Results.Ok(rows.Select(x=>new{x.Id,x.RecipeId,x.ProductId,productName=names.GetValueOrDefault(x.ProductId,"Item"),x.QuantityProduced,x.TotalCost,x.Status,x.Notes,x.OccurredAt}));});}
 static Guid StaffId(ClaimsPrincipal p)=>Guid.TryParse(p.FindFirst(ClaimTypes.NameIdentifier)?.Value,out var id)?id:throw new InvalidOperationException("Staff identity missing");
 static AuditEvent Audit(ClaimsPrincipal p,string action,string type,Guid id,string details,string? device=null)=>new(){StaffId=StaffId(p),Actor=p.Identity?.Name??"Staff",Action=action,EntityType=type,EntityId=id.ToString(),Details=details,DeviceId=device};
}
